// Usage: node benchmarks/eval/reversed-flows.mjs [--json]; needs target/release/layout-command.
// Right to left against left to right on the layered playground examples (generated by benchmarks/generate.py), every area
// set to the same direction: `lr`, `rl` as today, and `rl` with the experimental `singlePassReversed` (ADR 0020, S1-0).
// Prints crossings, bends, lines through nodes, width × height, and whether single pass ran.
import {readFileSync, readdirSync} from 'node:fs';
import {arqlet, normalizeArqlet, metrics, ROOT} from './lib.mjs';

const dir = `${ROOT}apps/playground/generated/examples/`;
const rows = [];
for (const file of readdirSync(dir).filter(f => f.endsWith('.json') && f !== 'index.json').sort()) {
  const raw = JSON.parse(readFileSync(dir + file, 'utf8'));
  const g = raw.graph ?? raw;
  if (!g.nodes || g.children || g.nodes.length > 200) continue;
  if (Object.values(g.containerStrategies ?? {}).some(s => s && s !== 'none') || (g.defaultStrategy && g.defaultStrategy !== 'none')) continue;
  const containers = new Set(g.nodes.map(n => n.parentId).filter(Boolean));
  for (const [variant, direction, options] of [['lr', 'lr', {}], ['rl', 'rl', {}], ['rl + singlePassReversed', 'rl', {singlePassReversed: true}]]) {
    const graph = {...g, defaultDirection: direction, containerDirections: Object.fromEntries([...containers].map(id => [id, direction]))};
    const {snapshot, ms} = arqlet({op: 'import', graph, limit: g.nodes.length, options});
    const m = metrics(normalizeArqlet(snapshot));
    rows.push({dataset: file.replace('.json', ''), variant, crossings: m.crossings, bends: m.bends, lineNodeHits: m.lineNodeHits,
      width: Math.round(m.width), height: Math.round(m.height),
      singlePass: (snapshot.layoutDiagnostics ?? []).some(d => d.startsWith('Single pass:')), ms: Math.round(ms)});
  }
}
if (process.argv.includes('--json')) for (const r of rows) console.log(JSON.stringify(r));
else {
  console.log('| dataset | variant | crossings | bends | line–node hits | width × height | single pass |');
  console.log('|---|---|---|---|---|---|---|');
  for (const r of rows) console.log(`| ${r.dataset} | ${r.variant} | ${r.crossings} | ${r.bends} | ${r.lineNodeHits} | ${r.width} × ${r.height} | ${r.singlePass ? 'yes' : 'no'} |`);
}
